import { useEffect, useRef, useState } from 'react';
import {
  Button,
  Image,
  ScrollView,
  StyleSheet,
  Text,
  View,
  type ImageSourcePropType,
} from 'react-native';
import { Dirs, FileSystem } from 'react-native-file-access';
import {
  superResolve,
  type SuperResolveResult,
} from 'react-native-mean-n-super-resolution';

// why: generated by example/scripts/generate-frames.mjs (frame0 = reference,
// frames 1-4 = the same scene shifted by a few pixels).
const FRAMES: ImageSourcePropType[] = [
  require('../assets/frames/frame0.png'),
  require('../assets/frames/frame1.png'),
  require('../assets/frames/frame2.png'),
  require('../assets/frames/frame3.png'),
  require('../assets/frames/frame4.png'),
];

// why: superResolve needs local file paths, but bundled images resolve to a Metro
// URL (debug), a bundle file (iOS release) or an Android drawable name (release).
async function copyFrame(asset: ImageSourcePropType, dest: string) {
  const uri = Image.resolveAssetSource(asset)?.uri;
  if (!uri) throw new Error(`cannot resolve bundled frame for ${dest}`);
  if (await FileSystem.exists(dest)) await FileSystem.unlink(dest);
  if (uri.startsWith('http')) {
    await FileSystem.fetch(uri, { path: dest });
  } else if (uri.startsWith('file://')) {
    await FileSystem.cp(decodeURI(uri.slice('file://'.length)), dest);
  } else {
    await FileSystem.cpAsset(`drawable/${uri}`, dest, 'resource');
  }
}

async function copyFrames(): Promise<string[]> {
  return Promise.all(
    FRAMES.map(async (asset, i) => {
      const dest = `${Dirs.CacheDir}/sr-frame${i}.png`;
      await copyFrame(asset, dest);
      return dest;
    })
  );
}

type Run = {
  result: SuperResolveResult;
  elapsedMs: number;
  ticksDuring: number;
};

export default function App() {
  const [ticks, setTicks] = useState(0);
  const ticksRef = useRef(0);
  const [busy, setBusy] = useState(false);
  const [run, setRun] = useState<Run | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [check, setCheck] = useState<string | null>(null);

  // why: JS heartbeat; it keeps counting while superResolve runs only if the
  // native work is off the JS thread (SR-CORE-05).
  useEffect(() => {
    const id = setInterval(() => {
      ticksRef.current += 1;
      setTicks(ticksRef.current);
    }, 100);
    return () => clearInterval(id);
  }, []);

  const onRun = async () => {
    setBusy(true);
    setError(null);
    setRun(null);
    try {
      const paths = await copyFrames();
      const startTicks = ticksRef.current;
      const start = Date.now();
      const result = await superResolve(paths);
      const next: Run = {
        result,
        elapsedMs: Date.now() - start,
        ticksDuring: ticksRef.current - startTicks,
      };
      console.log(`[superResolve] ${JSON.stringify(next)}`);
      setRun(next);
    } catch (e) {
      const message = e instanceof Error ? e.message : String(e);
      console.log(`[superResolve] error ${message}`);
      setError(message);
    } finally {
      setBusy(false);
    }
  };

  // why: device evidence that native SrError codes reach JS (SR-ERR-04/08) and
  // that concurrent default outputs get distinct files (SR-CORE-07).
  const runCheck = async (name: string, body: () => Promise<string>) => {
    setBusy(true);
    setCheck(null);
    let line: string;
    try {
      line = await body();
    } catch (e) {
      line = `rejected: ${e instanceof Error ? e.message : String(e)}`;
    }
    console.log(`[superResolve:${name}] ${line}`);
    setCheck(`${name}: ${line}`);
    setBusy(false);
  };

  const onMissingFile = () =>
    runCheck('missing-file', async () => {
      const paths = await copyFrames();
      paths[2] = `${Dirs.CacheDir}/does-not-exist.png`;
      const result = await superResolve(paths);
      return `unexpectedly resolved ${result.path}`;
    });

  const onConcurrent = () =>
    runCheck('concurrent', async () => {
      const paths = await copyFrames();
      const [a, b] = await Promise.all([
        superResolve(paths),
        superResolve(paths),
      ]);
      return `${a.path === b.path ? 'SAME' : 'distinct'} ${a.path} ${b.path}`;
    });

  return (
    <ScrollView contentContainerStyle={styles.container}>
      <Text style={styles.title}>superResolve demo</Text>
      <Text testID="heartbeat">JS heartbeat: {ticks}</Text>
      <Button
        title={busy ? 'Running…' : 'Super-resolve 5 frames (2×)'}
        onPress={onRun}
        disabled={busy}
      />
      <Text>Input: 5 × 640×480 PNG</Text>
      <Button
        title="Check: missing file"
        onPress={onMissingFile}
        disabled={busy}
      />
      <Button
        title="Check: 2 concurrent calls"
        onPress={onConcurrent}
        disabled={busy}
      />
      {check && (
        <Text testID="check" selectable style={styles.path}>
          {check}
        </Text>
      )}
      {run && (
        <View style={styles.result}>
          <Text testID="dims">
            Output: {run.result.width}×{run.result.height}
          </Text>
          <Text testID="framesUsed">framesUsed: {run.result.framesUsed}</Text>
          <Text>Elapsed: {run.elapsedMs} ms</Text>
          <Text>Heartbeat ticks during processing: {run.ticksDuring}</Text>
          <Text selectable style={styles.path}>
            {run.result.path}
          </Text>
          <Image
            source={{ uri: run.result.path }}
            style={[
              styles.image,
              { aspectRatio: run.result.width / run.result.height },
            ]}
          />
        </View>
      )}
      {error && <Text style={styles.error}>{error}</Text>}
    </ScrollView>
  );
}

const styles = StyleSheet.create({
  container: {
    alignItems: 'center',
    gap: 12,
    padding: 16,
    paddingTop: 64,
  },
  title: {
    fontSize: 20,
    fontWeight: '600',
  },
  result: {
    alignItems: 'center',
    gap: 4,
    width: '100%',
  },
  path: {
    fontSize: 11,
  },
  image: {
    width: '100%',
  },
  error: {
    color: 'crimson',
  },
});
